    function run(address log1, address log2, address log3) public {
        bool revertFirst;
        c.SetLogFile(log1); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            revertFirst = true;
        } else {
            revertFirst = false;
        }

        bool revertSecond;
        c.SetLogFile(log2); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            revertSecond = true;
        } else {
            revertSecond = false;
        }

        bool revertInit;
        c.Initialized(); bool __rev2 = __ESBMC_reverted(); if (__rev2) {
            revertInit = true;
        } else {
            revertInit = false;
        }

        bool revertThird;
        c.SetLogFile(log3); bool __rev3 = __ESBMC_reverted(); if (__rev3) {
            revertThird = true;
        } else {
            revertThird = false;
